//
// A live page is a <turbo-frame data-live-url="...">. Its content carries the
// state it was drawn from in data-revision. Now and then the frame asks the
// server whether anything changed; the server answers 304 when it did not, and
// with the frame when it did. One small request, no websocket and no
// reconnecting: the crowded conference Wi-Fi comes and goes, and a tick that
// is lost is only the next tick away.
const DEFAULT_INTERVAL = 250

// The request of the tick that is out, so a tap can stop it.
const inFlight = new WeakMap()

function watch(frame) {
  if (frame.dataset.liveWatched) return
  frame.dataset.liveWatched = "true"

  const url = frame.dataset.liveUrl
  const interval = Number(frame.dataset.liveInterval) || DEFAULT_INTERVAL

  const tick = async () => {
    if (inFlight.has(frame) || paused(frame)) return

    const controller = new AbortController()
    inFlight.set(frame, controller)
    try {
      const revision = revisionOf(frame)
      const response = await fetch(requestUrl(url, revision), {
        headers: { "Turbo-Frame": frame.id, Accept: "text/html, application/xhtml+xml" },
        cache: "no-store",
        signal: controller.signal
      })

