      // (a 401, an error page) is left alone; the next tick tries again.
      if (response.status === 304 || response.status === 204 || !response.ok) return

      const fresh = new DOMParser().parseFromString(await response.text(), "text/html").getElementById(frame.id)
      if (!fresh || revisionOf(fresh) === revisionOf(frame)) return

      frame.innerHTML = fresh.innerHTML
    } catch {
      // The network came and went. The next tick tries again.
    } finally {
      if (inFlight.get(frame) === controller) inFlight.delete(frame)
    }
  }

