/* "Your answer" is only on the option the player picked. */
.play-option__mark { display: none; }
.play-option.is-picked .play-option__mark,
.play-option.is-picked.is-correct .play-option__mark { display: inline; }
.play-option.is-correct .play-option__mark { color: var(--c-white); }

/* The list of the games of a quiz on the quiz page. */
.game-list { list-style: none; padding: 0; margin: 0; }
.game-item { display: flex; align-items: center; gap: 16px; justify-content: space-between; }
.game-item__code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 700; }
.game-item__meta { flex: 1; }

/* The counters are one line of text, so the numbers stay inside it: no flex
   items inside them, a screen reader and the QA tests read them as one string. */
.counter-pill { display: inline-block; }
.answers-counter { display: inline-block; }

/* ---------- Prizes ---------- */

/* "Number of winners" in the settings of a quiz. */
.input--number { max-width: 8em; }

/* The leaderboard of the big screen is the design's own: an <ol class="leaderboard">,
   one <li class="leader"> for every player. The star of the mockup is drawn by
   CSS, so it is switched off for the badge that says "Winner" - text, which a
   screen reader and the QA tests can read. */
.leader.is-winner .leader__name::after { content: none; }

/* The result on the phone of a player: their place and their points. */
.result-card__place-line {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(28px, 9vw, 48px);
  line-height: 1.1;
  margin-bottom: 10px;
